-- 校验：订单数量、商品件数、状态分布
SELECT COUNT(*) AS order_count,
       SUM(item_count) AS total_item_count,
       SUM(payable_amount) AS total_payable_amount
FROM orders
WHERE user_id = 10001;

SELECT order_status,
       COUNT(*) AS order_count
FROM orders
WHERE user_id = 10001
GROUP BY order_status
ORDER BY order_count DESC;

